138	+const problems = [];
139	+const check = (ok, msg) => { console.log(`${ok ? 'ĐẠT ' : 'LỖI '} ${msg}`); if (!ok) problems.push(msg); return ok; };
140	+
141	+// Mốc đo trên main 43cec90 (chép từ tests/boats-check.mjs): speed của 7 tàu chạy chung
142	+const MAIN_SPEEDS = [4.834048458375037, 3.4622229826636612, 3.367667659651488, 4.561683705076575, 4.302534147165716, 3.222870459780097, 4.6476020980626345];
143	+
144	+const srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url)));
